import {
  type ReactNode,
  type KeyboardEvent,
  type CSSProperties,
  useState,
  useCallback,
  useEffect,
  useRef,
  createContext,
  useContext,
} from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

/* ---- Context ---- */

type TabsContextValue = {
  value: string;
  setValue: (v: string) => void;
  orientation: 'horizontal' | 'vertical';
};

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs() {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('Tabs components must be used within <Tabs>');
  return ctx;
}

/* ---- Root ---- */

export type TabsProps = {
  defaultValue?: string;
  value?: string;
  onValueChange?: (value: string) => void;
  orientation?: 'horizontal' | 'vertical';
  children: ReactNode;
  className?: string;
};

export function Tabs({
  defaultValue = '',
  value: controlledValue,
  onValueChange,
  orientation = 'horizontal',
  children,
  className,
}: TabsProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const value = controlledValue ?? internalValue;

  const setValue = useCallback(
    (v: string) => {
      onValueChange ? onValueChange(v) : setInternalValue(v);
    },
    [onValueChange],
  );

  return (
    <TabsContext.Provider value={{ value, setValue, orientation }}>
      <div className={cn('tabs', orientation === 'vertical' && 'tabs--vertical', className)}>
        {children}
      </div>
    </TabsContext.Provider>
  );
}

/* ---- List ---- */

export type TabsListProps = {
  variant?: 'default' | 'line';
  animated?: boolean;
  children: ReactNode;
  className?: string;
};

export function TabsList({ variant = 'default', animated = false, children, className }: TabsListProps) {
  const { value } = useTabs();
  const listRef = useRef<HTMLDivElement>(null);
  const [indicatorStyle, setIndicatorStyle] = useState<CSSProperties>({ opacity: 0 });

  useEffect(() => {
    if (!animated || !listRef.current) return;

    const list = listRef.current;
    const active = list.querySelector<HTMLButtonElement>('[role="tab"][aria-selected="true"]');
    if (!active) {
      setIndicatorStyle((prev) => ({ ...prev, opacity: 0 }));
      return;
    }

    const listRect = list.getBoundingClientRect();
    const activeRect = active.getBoundingClientRect();

    setIndicatorStyle({
      opacity: 1,
      left: `${activeRect.left - listRect.left}px`,
      top: `${activeRect.top - listRect.top}px`,
      width: `${activeRect.width}px`,
      height: `${activeRect.height}px`,
    });
  }, [animated, value]);

  return (
    <div
      ref={listRef}
      role="tablist"
      className={cn(
        'tabs__list',
        variant === 'line' && 'tabs__list--line',
        animated && 'tabs__list--animated',
        className,
      )}
    >
      {animated && <div className="tabs__indicator" style={indicatorStyle} />}
      {children}
    </div>
  );
}

/* ---- Trigger ---- */

export type TabsTriggerProps = {
  value: string;
  disabled?: boolean;
  children: ReactNode;
  className?: string;
};

export function TabsTrigger({ value: triggerValue, disabled = false, children, className }: TabsTriggerProps) {
  const { value, setValue, orientation } = useTabs();
  const isActive = value === triggerValue;

  const handleKeyDown = (e: KeyboardEvent<HTMLButtonElement>) => {
    const el = e.currentTarget;
    const list = el.parentElement;
    if (!list) return;

    const triggers = Array.from(list.querySelectorAll<HTMLButtonElement>('[role="tab"]:not([disabled])'));
    const idx = triggers.indexOf(el);
    let next = -1;

    const isHorizontal = orientation === 'horizontal';

    if ((isHorizontal && e.key === 'ArrowRight') || (!isHorizontal && e.key === 'ArrowDown')) {
      next = idx < triggers.length - 1 ? idx + 1 : 0;
    } else if ((isHorizontal && e.key === 'ArrowLeft') || (!isHorizontal && e.key === 'ArrowUp')) {
      next = idx > 0 ? idx - 1 : triggers.length - 1;
    }

    if (next >= 0) {
      e.preventDefault();
      triggers[next].focus();
      triggers[next].click();
    }
  };

  return (
    <button
      type="button"
      role="tab"
      aria-selected={isActive}
      tabIndex={isActive ? 0 : -1}
      disabled={disabled}
      className={cn(
        'tabs__trigger',
        isActive && 'tabs__trigger--active',
        disabled && 'tabs__trigger--disabled',
        className,
      )}
      onClick={() => { if (!disabled) setValue(triggerValue); }}
      onKeyDown={handleKeyDown}
    >
      {children}
    </button>
  );
}

/* ---- Content ---- */

export type TabsContentProps = {
  value: string;
  children: ReactNode;
  className?: string;
};

export function TabsContent({ value: contentValue, children, className }: TabsContentProps) {
  const { value } = useTabs();
  if (value !== contentValue) return null;

  return (
    <div role="tabpanel" tabIndex={0} className={cn('tabs__content', className)}>
      {children}
    </div>
  );
}

/* -------------------------------------------------------------------------
   Tabs

   Tabbed content switcher. Horizontal or vertical.
   Variants: default (pill bg), line (underline indicator).

   Parts: .tabs, .tabs__list, .tabs__trigger, .tabs__content
   ------------------------------------------------------------------------- */

/* ---- Root ---- */

.tabs {
  display: flex;
  flex-direction: column;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
}

.tabs--vertical {
  flex-direction: row;
  gap: var(--spacing-4, 16px);
}

/* ---- List ---- */

.tabs__list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;
  padding: 3px;
  background-color: var(--muted);
  border-radius: var(--radius-lg);
}

.tabs__list .tabs__trigger {
  flex: 1;
  text-align: center;
}

/* Line variant: no bg, bottom border */
.tabs__list--line {
  background: none;
  border-radius: 0;
  padding: 0;
  gap: 0;
  border-bottom: var(--stroke-hairline) solid var(--border);
}

/* Vertical list */
.tabs--vertical .tabs__list {
  flex-direction: column;
  align-items: stretch;
}

.tabs--vertical .tabs__list:not(.tabs__list--line) {
  border-radius: var(--radius-lg);
}

.tabs--vertical .tabs__list--line {
  border-bottom: none;
  border-right: var(--stroke-hairline) solid var(--border);
}

/* ---- Animated indicator ---- */

.tabs__list--animated {
  position: relative;
}

.tabs__indicator {
  position: absolute;
  border-radius: var(--radius-md);
  background-color: var(--background);
  box-shadow: var(--shadow-2xs);
  pointer-events: none;
  z-index: 0;
  transition:
    left 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    top 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    width 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    height 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    opacity var(--duration-200) var(--easing-in-out);
}

.tabs__list--animated .tabs__trigger {
  position: relative;
  z-index: 1;
}

.tabs__list--animated .tabs__trigger--active {
  background: none;
  box-shadow: none;
}

/* ---- Trigger ---- */

.tabs__trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2, 8px);
  padding: var(--spacing-2, 8px) var(--spacing-3, 12px);
  border: none;
  border-radius: var(--radius-md);
  background: none;
  color: color-mix(in srgb, var(--foreground) 55%, var(--muted-foreground));
  font-family: inherit;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    color var(--duration-150) var(--easing-in-out),
    background-color var(--duration-150) var(--easing-in-out),
    box-shadow var(--duration-150) var(--easing-in-out);
}

.tabs__trigger:hover {
  color: var(--foreground);
}

.tabs__trigger:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color);
  outline-offset: -2px;
}

/* Active (default variant) */
.tabs__trigger--active {
  background-color: var(--background);
  color: var(--foreground);
  box-shadow: var(--shadow-2xs);
}

/* Disabled */
.tabs__trigger--disabled {
  color: var(--muted-foreground);
  opacity: var(--opacity-50);
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Line variant triggers ---- */

.tabs__list--line .tabs__trigger {
  border-radius: 0;
  padding: var(--spacing-2, 8px) var(--spacing-4, 16px);
  position: relative;
}

.tabs__list--line .tabs__trigger::after {
  content: "";
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: var(--stroke-medium);
  background-color: transparent;
  transition: background-color var(--duration-150) var(--easing-in-out);
}

.tabs__list--line .tabs__trigger--active {
  background: none;
  box-shadow: none;
  color: var(--foreground);
}

.tabs__list--line .tabs__trigger--active::after {
  background-color: var(--primary);
}

/* Line vertical */
.tabs--vertical .tabs__list--line .tabs__trigger::after {
  bottom: auto;
  left: auto;
  right: -1px;
  top: 0;
  width: var(--stroke-medium);
  height: 100%;
}

/* ---- Trigger icon ---- */

.tabs__trigger-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1em;
  height: 1em;
}

.tabs__trigger-icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Content ---- */

.tabs__content {
  padding-top: var(--spacing-4, 16px);
}

.tabs--vertical .tabs__content {
  padding-top: 0;
  flex: 1;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .tabs__trigger,
  .tabs__list--line .tabs__trigger::after {
    transition-duration: 0ms;
  }
}

